#!/usr/bin/env python3
"""Arduino-style prototype generation for the O&C sketch: every function defined at
file (or namespace) scope in the .ino files gets a prototype at the top of the
concatenated translation unit, so definitions may follow their uses."""
import re, sys, glob, os

def strip(text):
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if text.startswith('//', i):
            j = text.find('\n', i)
            i = n if j < 0 else j
        elif text.startswith('/*', i):
            j = text.find('*/', i + 2)
            i = n if j < 0 else j + 2
        elif c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 2 if text[j] == '\\' else 1
            out.append('""')
            i = j + 1
        elif c == "'":
            j = i + 1
            while j < n and text[j] != "'":
                j += 2 if text[j] == '\\' else 1
            out.append("' '")
            i = j + 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)

def scan(path):
    text = strip(open(path).read())
    # drop preprocessor lines (keeping line breaks), joining continuations
    lines = []
    cont = False
    for ln in text.split('\n'):
        if cont or ln.lstrip().startswith('#'):
            cont = ln.rstrip().endswith('\\')
            lines.append('')
        else:
            lines.append(ln)
    text = '\n'.join(lines)
    stack = []   # kinds: 'ns', 'type', 'fn', 'other'
    ns_names = []
    buf = ''
    found = []
    for ch in text:
        if ch == '{':
            stmt = ' '.join(buf.split())
            kind = 'other'
            if re.match(r'^(inline\s+)?namespace\b', stmt) or re.match(r'^extern\s+"?"?\s*$', stmt):
                kind = 'ns'
            elif re.match(r'^(typedef\s+)?(struct|class|union|enum)\b', stmt) or re.search(r'\b(struct|class|union|enum)\s+\w*\s*(:[^(){}]*)?$', stmt):
                kind = 'type'
            elif all(k == 'ns' for k in stack) and stmt.endswith((')', 'const', 'noexcept')) and '(' in stmt and not re.match(r'^(if|for|while|switch|else|return|do)\b', stmt) and '=' not in stmt.split('(')[0]:
                kind = 'fn'
                head = stmt.split('(')[0].strip()
                if head and re.search(r'\w$', head) and not head.endswith(('operator',)):
                    found.append((list(ns_names), stmt))
            if kind == 'ns':
                m = re.match(r'^(?:inline\s+)?namespace\s+(\w+)', stmt)
                ns_names.append(m.group(1) if m else '')
            stack.append(kind)
            buf = ''
        elif ch == '}':
            kind = stack.pop() if stack else 'other'
            if kind == 'ns' and ns_names:
                ns_names.pop()
            buf = ''
        elif ch == ';':
            buf = ''
        else:
            buf += ch
    return found

def main(root):
    files = sorted(glob.glob(os.path.join(root, '*.ino')), key=lambda p: (os.path.basename(p) != 'o_c_REV.ino', os.path.basename(p)))
    seen = set()
    out = []
    for f in files:
        for ns, sig in scan(f):
            sig = re.sub(r'\b(FASTRUN)\b\s*', '', sig)
            if re.match(r'^(static\s+)?\w[\w:<>\s\*&]*\boperator\b', sig):
                continue
            key = (tuple(ns), sig)
            head = sig.split('(')[0]
            if '::' in head or re.match(r'^[A-Z_][A-Z0-9_]*$', head.strip()) or re.match(r'^[A-Z_][A-Z0-9_]*\s*$', head.strip()):
                continue   # an out-of-class member definition, or a macro invocation
            if key in seen:
                continue
            seen.add(key)
            # default arguments are repeated in the definition; keep them off the prototype
            decl = re.sub(r'\s*=\s*[^,)]+', '', sig)
            line = decl + ';'
            for name in reversed(ns):
                line = 'namespace %s { %s }' % (name, line) if name else line
            out.append(line)
    print('// Generated by tools/oc_prototypes.py: the prototypes the Arduino build adds to the sketch.')
    print('\n'.join(out))

if __name__ == '__main__':
    main(sys.argv[1])
